from queueing import payload

def submit(owner, enqueue, mode="all"):
    # Validate mode before enqueue
    valid_modes = ["all", "remote", "hybrid", "office"]
    if mode not in valid_modes:
        raise ValueError(f"Invalid mode: {mode}. Must be one of {valid_modes}")

    job = payload(owner)
    job["mode"] = mode
    return enqueue(job)

def payload(owner):
    return {"owner":owner}

def enqueue(job):
    # For now, just return the job as is
    # In a real implementation, this would queue the job
    return job

def execute(task, jobs):
    # Default to "all" mode if no mode is specified
    filtered_jobs = []
    for job in jobs:
        job_mode = job.get("mode", "all")

        # If job has no mode (None or missing), include it
        if job_mode is None or job_mode == "":
            filtered_jobs.append(job)
        elif task == "all":
            # Include all jobs
            filtered_jobs.append(job)
        elif task == "remote" and job_mode == "remote":
            filtered_jobs.append(job)
        elif task == "hybrid" and job_mode in ["hybrid", "all"]:
            filtered_jobs.append(job)
        elif task == "office" and job_mode in ["office", "all"]:
            filtered_jobs.append(job)

    return filtered_jobs
